import React, { useEffect, useState } from 'react';

export default function Dashboard({ user, token }) {
  const [me, setMe] = useState(user);
  const [events, setEvents] = useState([]);
  const [msg, setMsg] = useState('');
  const [reports, setReports] = useState(null);
  const [activities, setActivities] = useState(null);
  const [ngoPanel, setNgoPanel] = useState(null); // volunteers, donations, events
  const [ngoList, setNgoList] = useState([]);     // for admin: pending NGOs

  // Load user & events
  useEffect(() => {
    if (token) {
      fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/dashboard/me',
        { headers: { Authorization: `Bearer ${token}` } }
      ).then(r => r.json()).then(d => { if (d.user) setMe(d.user); });

      fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/events/all')
        .then(r => r.json()).then(setEvents);
    }
  }, [token]);


  // Load volunteer activity for Volunteers/Donors
  useEffect(() => {
    if (token && me?.role === 'Volunteer/Donor') {
      fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/dashboard/my-activities',
        { headers: { Authorization: `Bearer ${token}` } }
      ).then(r => r.json()).then(setActivities)
        .catch(() => setActivities(null));
    }
  }, [token, me]);


  // NGO dashboard panel: volunteers, donations, event registrations
  useEffect(() => {
    if (token && me?.role === 'NGO') {
      fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/ngo/panel',
        { headers: { Authorization: `Bearer ${token}` } }
      ).then(r => r.json()).then(setNgoPanel);
    }
  }, [token, me]);


  // Admin reports & pending NGOs
  useEffect(() => {
    if (token && me?.role === 'Admin') {

      fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/admin/reports',
        { headers: { Authorization: `Bearer ${token}` } }
      ).then(r => r.json()).then(setReports);

      fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/admin/ngos',
        { headers: { Authorization: `Bearer ${token}` } }
      ).then(r => r.json()).then(setNgoList);
    }
  }, [token, me]);

  if (!me) return <div>Please login to see your dashboard.</div>;

  return (
    <div className="dashboard">
      <h2>{me.role} Dashboard</h2>

      {/* ------------ VOLUNTEER / DONOR DASHBOARD ------------ */}
      {me.role === 'Volunteer/Donor' && (
        <>
          <VolunteerDonorSection
            me={me}
            events={events}
            token={token}
            msg={msg}
            setMsg={setMsg}
            activities={activities}
          />
        </>
      )}

      {/* ------------ NGO DASHBOARD ------------ */}
      {me.role === 'NGO' && (
        <>
          <NgoDashboard
            token={token}
            msg={msg}
            setMsg={setMsg}
            events={events}
            setEvents={setEvents}
            ngoPanel={ngoPanel}
          />
        </>
      )}

      {/* ------------ ADMIN DASHBOARD ------------ */}
      {me.role === 'Admin' && (
        <>
          <AdminDashboard
            reports={reports}
            ngoList={ngoList}
            token={token}
            setMsg={setMsg}
          />
        </>
      )}

      <p className="msg">{msg}</p>
    </div>
  );
}


/* ---------------------------------------------------------
   VOLUNTEER / DONOR DASHBOARD SECTION
----------------------------------------------------------*/
function VolunteerDonorSection({ me, events, token, msg, setMsg, activities }) {
  return (
    <div className="panel">
      <h3>Recognition & Badges</h3>
      <p><strong>Name:</strong> {me.name}</p>
      <p><strong>Email:</strong> {me.email}</p>
      <p><strong>Points:</strong> {me.points}</p>
      <p><strong>Level:</strong>
        {me.points >= 200 ? 'Gold' :
          me.points >= 100 ? 'Silver' :
            me.points >= 50 ? 'Bronze' :
              me.points >= 10 ? 'Member' : 'New'}
      </p>

      <h3>Actions</h3>
      <h4>Give Feedback</h4>
      <Feedback token={token} setMsg={setMsg} />

      <h4>Donate</h4>
      <Donate token={token} setMsg={setMsg} />

      <h4>Volunteer for Event</h4>
      <Volunteer token={token} events={events} setMsg={setMsg} />
    </div>
  );
}


/* ---------------------------------------------------------
   NGO DASHBOARD SECTION
----------------------------------------------------------*/
function NgoDashboard({ token, msg, setMsg, events, setEvents, ngoPanel }) {

  async function createEvent(e) {
    e.preventDefault();
    const fd = new FormData(e.target);
    const res = await fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/ngo/events/create', {
      method: 'POST',
      headers: { Authorization: `Bearer ${token}` },
      body: fd
    });
    const d = await res.json();
    setMsg(d.message);

    // refresh events
    fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/events/all')
      .then(r => r.json()).then(setEvents);
  }

  async function removeEvent(id) {
    const res = await fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/ngo/events/remove/' + id, {
      method: 'DELETE',
      headers: { Authorization: `Bearer ${token}` }
    });
    const d = await res.json();
    setMsg(d.message);

    // refresh events
    fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/events/all')
      .then(r => r.json()).then(setEvents);
  }

  return (
    <div className="panel">
      <h3>NGO Controls</h3>

      <h4>Create New Event</h4>
      <form onSubmit={createEvent}>
        <input name="title" placeholder="Event Title" required />
        <textarea name="description" placeholder="Event Description" required />
        <input type="file" name="image" />
        <button>Create Event</button>
      </form>

      <h4>Your Events</h4>
      {events.filter(e => e.ngo_id === ngoPanel?.ngo_id).map(ev => (
        <div key={ev.id} style={{ display: "flex", gap: 10, marginBottom: 10 }}>
          <strong>{ev.title}</strong>
          <button onClick={() => removeEvent(ev.id)}>Remove</button>
        </div>
      ))}

      <h4>Volunteers for Your Events</h4>
      <ul>
        {ngoPanel?.volunteers?.map(v => (
          <li key={v.id}>{v.name} joined {v.event_title}</li>
        ))}
      </ul>

      <h4>Donations Received</h4>
      <ul>
        {ngoPanel?.donations?.map(d => (
          <li key={d.id}>{d.name}: ₹{d.amount}</li>
        ))}
      </ul>

      <h4>Give Feedback to Volunteer/Donor</h4>
      <Feedback token={token} setMsg={setMsg} />
    </div>
  );
}


/* ---------------------------------------------------------
   ADMIN DASHBOARD SECTION
----------------------------------------------------------*/
function AdminDashboard({ reports, ngoList, token, setMsg }) {

  async function approveNgo(id, action) {
    const res = await fetch((process.env.REACT_APP_API || 'http://localhost:4000') + `/api/admin/ngos/${action}/${id}`, {
      method: 'POST',
      headers: { Authorization: `Bearer ${token}` }
    });
    const d = await res.json();
    setMsg(d.message);
  }

  return (
    <div className="panel">
      <h3>Admin Panel</h3>

      <h4>Pending NGOs</h4>
      <ul>
        {ngoList.map(n => (
          <li key={n.id}>
            {n.name} — {n.email}
            <button onClick={() => approveNgo(n.id, 'approve')}>Approve</button>
            <button onClick={() => approveNgo(n.id, 'reject')}>Reject</button>
          </li>
        ))}
      </ul>

      <h4>Platform Reports</h4>
      {reports ? (
        <>
          <h5>Feedback</h5>
          <ul>{reports.feedbacks?.map(f => (
            <li key={f.id}><strong>{f.name}</strong>: {f.text}</li>
          ))}</ul>

          <h5>Donations</h5>
          <ul>{reports.donations?.map(d => (
            <li key={d.id}>{d.name}: ₹{d.amount}</li>
          ))}</ul>

          <h5>Volunteers</h5>
          <ul>{reports.volunteers?.map(v => (
            <li key={v.id}>{v.name} → {v.event_title}</li>
          ))}</ul>
        </>
      ) : <p>Loading reports...</p>}
    </div>
  );
}


/* ---------------------------------------------------------
   FEEDBACK / DONATE / VOLUNTEER COMPONENTS
----------------------------------------------------------*/

function Feedback({ token, setMsg }) {
  const [text, setText] = useState('');
  async function submit(e) {
    e.preventDefault();
    const res = await fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/actions/feedback', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${token}` },
      body: JSON.stringify({ text })
    });
    setMsg((await res.json()).message || 'Feedback sent');
  }
  return (
    <form onSubmit={submit}>
      <textarea value={text} onChange={e => setText(e.target.value)} placeholder="Write feedback" />
      <button>Send Feedback</button>
    </form>
  );
}

function Donate({ token, setMsg }) {
  const [amount, setAmount] = useState('');
  async function submit(e) {
    e.preventDefault();
    const res = await fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/actions/donate', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${token}` },
      body: JSON.stringify({ amount })
    });
    setMsg((await res.json()).message || 'Donated');
  }
  return (
    <form onSubmit={submit}>
      <input value={amount} onChange={e => setAmount(e.target.value)} placeholder="Amount" />
      <button>Donate</button>
    </form>
  );
}

function Volunteer({ token, events, setMsg }) {
  const [eventId, setEventId] = useState('');
  async function submit(e) {
    e.preventDefault();
    const res = await fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/actions/volunteer', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${token}` },
      body: JSON.stringify({ event_id: eventId })
    });
    setMsg((await res.json()).message || 'Registered');
  }
  return (
    <form onSubmit={submit}>
      <select value={eventId} onChange={e => setEventId(e.target.value)}>
        <option value="">Select event</option>
        {events.map(ev => (
          <option key={ev.id} value={ev.id}>{ev.title}</option>
        ))}
      </select>
      <button>Sign Up</button>
    </form>
  );
}
